import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void bmm_kernel(
    const half* __restrict__ A,
    const half* __restrict__ B,
    half* __restrict__ C,
    int batch_size,
    int m,
    int k,
    int n
) {
    int batch_idx = blockIdx.z;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || row >= m || col >= n) return;

    float sum = 0.0f;
    const half* a_row = A + batch_idx * m * k + row * k;
    const half* b_col = B + batch_idx * k * n + col;

    for (int i = 0; i < k; ++i) {
        sum += __half2float(a_row[i]) * __half2float(b_col[i * n]);
    }

    C[batch_idx * m * n + row * n + col] = __float2half(sum);
}

void launch_bmm_kernel(
    const half* A,
    const half* B,
    half* C,
    int batch_size,
    int m,
    int k,
    int n
) {
    dim3 block_size(16, 16);
    dim3 grid_size(
        (n + block_size.x - 1) / block_size.x,
        (m + block_size.y - 1) / block_size.y,
        batch_size
    );

    bmm_kernel<<<grid_size, block_size>>>(
        A, B, C, batch_size, m, k, n
    );
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="bmm_cuda",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["launch_bmm_kernel"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self):
            super(ModelNew, self).__init__()

        def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
            batch_size, m, k = A.shape
            _, _, n = B.shape

            # Ensure inputs are contiguous and on GPU
            A = A.contiguous().to(torch.float16).cuda()
            B = B.contiguous().to(torch.float16).cuda()

            # Create output tensor
            C = torch.empty(batch_size, m, n, dtype=torch.float16, device='cuda')

            # Launch kernel
            module.launch_bmm_kernel(
                A.data_ptr(),
                B.data_ptr(),
                C.data_ptr(),
                batch_size,
                m,
                k,
                n
            )

            return C

    return ModelNew

ModelNew = compile_and_run()
